#!/usr/bin/env python3
"""Render final frozen comparison as Korean Markdown and original charts."""
import csv,json,os
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/lineage-mpl')
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).resolve().parent
r=json.loads((HERE/'results/report.json').read_text());assert len(r['sheets'])==18,'Wait for all 8 historical + 2 real ROI + 8 synthetic sheets'
a=r['aggregate'];figures=HERE/'figures';figures.mkdir(exist_ok=True)
pct=lambda x:f'{100*x:.2f}%'
metrics=lambda x:' / '.join(pct(x[k]) for k in ['precision','recall','f1'])
fig,axes=plt.subplots(1,3,figsize=(15,4.6),layout='constrained')
labels=['OPEN100 historical (8)','Pahala real ROI (2)','Synthetic regression (8)'];groups=['open100','pahala','synthetic'];x=np.arange(3)
for ax,metric,key,title in [(axes[0],'connections','recall','Connection recall'),(axes[1],'connections','f1','Connection F1'),(axes[2],None,None,'Mean of paired sheet median latency')]:
 for i,variant in enumerate(['v3','v4']):
  values=[a[g][variant][metric][key]*100 if metric else a[g][variant]['mean_sheet_median_seconds'] for g in groups]
  bars=ax.bar(x+(i-.5)*.34,values,.32,label=variant,color=['#98a1ac','#12756f'][i]);ax.bar_label(bars,labels=[f'{v:.2f}'+('%' if metric else 's') for v in values],fontsize=9,padding=3)
 ax.set_xticks(x,labels,fontsize=9,rotation=12);ax.set_title(title);ax.spines[['top','right']].set_visible(False);ax.set_ylim(0,max(ax.get_ylim()[1]*1.12,10));ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
axes[0].legend(frameon=False);fig.suptitle('Frozen v3 / v4 | same IoU >= 0.50 matching and equipment adjacency',fontsize=14)
fig.savefig(figures/'recall-speed.png',dpi=160);plt.close(fig)
fig,ax=plt.subplots(figsize=(9,4.1),layout='constrained');names=['Recovered','Missing endpoint symbol','Weak-circle port constraint','Line / port routing'];keys=['recovered','missing_symbol','disabled_symbol_port','line_or_port_routing']
for i,v in enumerate(['v3','v4']):
 values=[a['open100'][v]['miss_attribution'].get(k,0) for k in keys];bars=ax.barh(np.arange(4)+(i-.5)*.32,values,.3,label=v,color=['#98a1ac','#12756f'][i]);ax.bar_label(bars,padding=3)
ax.set_yticks(np.arange(4),names);ax.invert_yaxis();ax.set_xlim(0,900);ax.set_title('OPEN100: mutually exclusive error attribution (priority-based)');ax.legend(frameon=False);ax.spines[['top','right']].set_visible(False);fig.savefig(figures/'miss-attribution.png',dpi=160);plt.close(fig)
with (HERE/'per-sheet.csv').open('w',newline='') as f:
 writer=csv.writer(f,lineterminator='\n');writer.writerow(['group','id','version','symbol_tp','symbol_fp','symbol_fn','connection_tp','connection_fp','connection_fn','connection_precision','connection_recall','connection_f1','median_seconds','min_seconds','max_seconds'])
 for s in r['sheets']:
  for version,d in s['variants'].items():
   l,e,t=d['scores']['localization'],d['scores']['connections'],d['timing'];writer.writerow([s['group'],s['id'],version,*[l[k] for k in ['tp','fp','fn']],*[e[k] for k in ['tp','fp','fn','precision','recall','f1']],*[t[k] for k in ['median','min','max']]])
lines=['# v4 연결 누락 원인·재현율·속도 개선 평가','',f"기준 앱 `2e111c42f33a02fb253b82a49e993c661e690ef3` → 개선 앱 `ab04ed8e529d8c605995cd5e8fbaa87b2b4ffeaf`. 평가 {r['evaluated_at']}. [CI](https://github.com/haesookimDev/lineage-drawings/actions/runs/40642672622).",'',f"기존 실제 OPEN100 8장의 연결 재현율은 **{pct(a['open100']['v3']['connections']['recall'])}→{pct(a['open100']['v4']['connections']['recall'])}**, 연결 F1은 **{pct(a['open100']['v3']['connections']['f1'])}→{pct(a['open100']['v4']['connections']['f1'])}**다. OCR+추출의 반복 측정 지연은 도면별 중앙값의 평균으로 **{a['open100']['v3']['mean_sheet_median_seconds']:.3f}초→{a['open100']['v4']['mean_sheet_median_seconds']:.3f}초**다.",'','## 같은 기준의 결과','','| 평가 범위 | 버전 | 연결 P / R / F1 | 기호 위치 F1 | 도면별 중앙값 평균 |','|---|---|---|---:|---:|']
for g,label in zip(groups,labels):
 for v in ['v3','v4']:
  d=a[g][v];lines.append(f"| {label} | {v} | {metrics(d['connections'])} | {pct(d['localization']['f1'])} | {d['mean_sheet_median_seconds']:.3f}초 |")
lines+=['','![재현율·F1·속도 비교](figures/recall-speed.png)','','## 다른 공개 실제 도면 검증','','추가 원본은 [미국 EPA 공개 Pāhala WWTP 설계 문서](https://www.epa.gov/system/files/documents/2021-08/pahala-wwtp-design-build-drawings-2021-07-23.pdf)의 23쪽(P-601)·24쪽(P-602)다. OPEN100과 다른 Brown and Caldwell의 실제 프로젝트 설계 문서이며, 시공 완료 도면이나 운전 검증 문서라는 뜻은 아니다. 원본의 "general understanding of the project concept" 성격을 보존한다.','',f"기호 48개·연결 54개를 포함하는 **사전 지정 공정 영역 두 곳만** 채점했다. 새 실제 영역의 연결 재현율은 {pct(a['pahala']['v3']['connections']['recall'])}→{pct(a['pahala']['v4']['connections']['recall'])}, F1은 {pct(a['pahala']['v3']['connections']['f1'])}→{pct(a['pahala']['v4']['connections']['f1'])}다. 전체 페이지를 PNG로 입력했으며 원본 PDF의 텍스트·벡터·주석은 모델에 주지 않았다.",'','정답은 원본을 보고 작성한 단일 시각 주석이다. 모델 예측을 보지 않고 영역·기호·관계를 먼저 기록했고 이후 변경하지 않았다. SCADA 버스의 모호한 의미와 23쪽 플로트 조립체는 사전 제외했다. [계획](PLAN.json), [주석](pahala-labels.json), [고정 시점·해시](FROZEN.json)에 범위가 있다. 해당 도면을 모델 학습·문턱값 조정에 쓰지 않았다. 공개 외부 기관의 인증된 전체 정답셋, 여러 새 프로젝트의 검증 또는 독립적인 전문가 이중 주석으로 표현하지 않는다. 원본 PDF·페이지 이미지·전체 OCR 문자는 저장소에 재배포하지 않는다.','','| 새 실제 영역 | 기호 수 / 정답 연결 수 | v3 연결 TP / FP / FN | v4 연결 TP / FP / FN |','|---|---:|---|---|']
for s in r['sheets']:
 if s['group']=='pahala':
  d=[s['variants'][v]['scores']['connections'] for v in ['v3','v4']];lines.append(f"| {s['id']} | {s['gt_symbols']} / {s['gt_connections']} | {' / '.join(str(d[0][k]) for k in ['tp','fp','fn'])} | {' / '.join(str(d[1][k]) for k in ['tp','fp','fn'])} |")
lines+=['','## 누락 원인과 수정','','기존 정답 연결 1,393개를 순서가 있는 진단으로 나누면 복구 153개, 끝점 기호 누락 797개, 검출됐지만 연결 자격이 꺼진 원형 후보 99개, 선·포트 추적 누락 344개였다. 독립적인 인과 비율은 아니며 누락 기호가 있으면 우선 해당 범주로 센다. 누락 끝점은 밸브 788회·탱크 119회·펌프 133회·계기 35회·연속 표지 10회로 반복 집계됐다. 서로 다른 누락 기호 개수와 다르다.','','- 최소 선 검출 길이 12px→7px: 작은 기호 사이·계기 끝의 짧은 선을 더 보존한다.','- 포트 경계 2px 보정: 기호 윤곽과 선 중심의 작은 어긋남을 허용한다. 큰 간격을 임의로 연결하지 않는다.','- 약한 원형 후보: 실제 선 끝에서만 잎 노드로 붙인다. 통과하는 기존 선망을 끊는 장벽으로 사용하지 않는다.','- 일반 스타일: 기존 연결을 보존하고 짧은 선의 두 번째 추적으로 최대 100개를 보충한다. 총 상한은 500개이며 추가 FP가 생길 수 있다. 지원 스타일의 점/T자/무점 X 정책과 달리 일반 경로의 교차는 계속 검토가 필요하다.','- 템플릿 검색: 73개 개발 전용 자산을 바꾸지 않고, 반해상도 후보 탐색 후 원본 NCC 0.78 검증으로 전환한다. 근사 검색이라 일부 위치 검출은 달라진다.','','![누락 원인 비교](figures/miss-attribution.png)','','최종 잔여 분류의 `disabled_symbol_port`는 호환성을 위한 필드명이다. v4에서는 완전히 끈 접점이 아니라 약한 원형 후보의 잎 접점 제약이 남은 경우를 뜻한다. 기호 누락이 여전히 가장 큰 원인이라 연결 완전성은 충분하지 않다.','','## 부작용과 실패 결과','','넓은 폐곡선·촘촘한 원형 후보를 추가한 시도는 오검출과 경로 차단을 늘려 폐기했다. [개발 중간 결과](iterations/short-lines-fast-search/report.json)를 보존했다. 새 포트 그래프를 일반 합성 스타일에 무조건 적용하는 시도도 F1이 약 2.75%→1.03%로 낮아져 채택하지 않았다. 일반 경로의 보충 방식만 채택했다. 이 합성 집합은 이전 작업에서 이미 보았으므로 새 보류셋이 아니다.','',f"최종 합성 회귀 8장에서 연결 F1은 {pct(a['synthetic']['v3']['connections']['f1'])}→{pct(a['synthetic']['v4']['connections']['f1'])}지만 정밀도는 {pct(a['synthetic']['v3']['connections']['precision'])}→{pct(a['synthetic']['v4']['connections']['precision'])}다. 추가 FP의 비용도 함께 봐야 한다.",'',f"OPEN100의 위치 F1은 {pct(a['open100']['v3']['localization']['f1'])}→{pct(a['open100']['v4']['localization']['f1'])}로 소폭 낮아졌다. 정답 기호 영역을 준 연결 진단도 F1 {pct(a['open100']['v3']['oracle_boxes']['f1'])}→{pct(a['open100']['v4']['oracle_boxes']['f1'])}다. 이 진단은 실제 end-to-end 성능이 아니다. 전체 평균이 올라가도 도면별로 연결 재현율·F1이 내려가는 사례가 있다.",'','## 도면별 연결 결과','','| 집합 / ID | v3 P / R / F1 | v4 P / R / F1 | v3→v4 중앙값 초 |','|---|---|---|---|']
for s in r['sheets']:
 v3,v4=s['variants']['v3'],s['variants']['v4'];lines.append(f"| {s['group']} / {s['id']} | {metrics(v3['scores']['connections'])} | {metrics(v4['scores']['connections'])} | {v3['timing']['median']:.3f}→{v4['timing']['median']:.3f} |")
lines+=['','## 측정·재현·운영 반영','','기준 v3의 전체 backend/모델은 Git 커밋으로 격리해 로드한다. 같은 클래스 무관 IoU 0.50 일대일 매칭과 무방향 장비 인접 관계를 썼다. 매칭 실패 끝점도 FP로 센다. 기존 OPEN100 8장은 역사적 회귀이며 이번에 독립적인 새 블라인드 결과가 된 것은 아니다. 73개 모델 자산의 학습 원본은 여전히 OPEN100 0–3뿐이다. 모든 자동 결과의 종류는 미분류, 상태는 검토 필요이며 국제표준 식별 성공률을 주장하지 않는다.','','각 도면·버전을 순차로 3회씩 측정하고 반복마다 실행 순서를 뒤집었다. 18개 도면의 모든 반복에서 기호 영역·연결 쌍의 동일성도 검사했다. 지연은 이미지 디코딩·파일 전송·내보내기·정답 영역 진단을 제외한 OCR+추출 시간이다. 도면별 중앙값·최솟값·최댓값은 [CSV](per-sheet.csv), 모든 원시 실행 시간·수치·후보는 [결과](results/report.json)에 있다. 단일 CPU 호스트의 반복 측정으로 부하 시험이나 SLA를 대신하지 않는다.','','로컬 전체 회귀 테스트 31개가 통과했고 CI 테스트·프런트 빌드도 확인했다. 실제 배포 결과와 외부 업로드·검토 저장 검증은 [운영 검증](../../DEPLOYED_V4_VERIFICATION.ko.md)에 기록한다. 앱 커밋은 문서 커밋과 구분하며 실행 Pod의 코드·모델 해시로 반영을 확인한다.','','```bash','export PATH=/tmp/lineage-ocr-bookworm/bin:$PATH  # 또는 동일 버전 Tesseract 5.3.0 + eng/kor + TSV','export OMP_NUM_THREADS=1','.venv/bin/python scripts/fetch_public_benchmark.py','.venv/bin/python scripts/fetch_v3_confirmation.py','# Pahala 원본의 고정 SHA와 2400px 렌더링: fetch_pahala.py 참조','.venv/bin/python evaluation/v4/fetch_pahala.py','.venv/bin/python evaluation/v4/evaluate.py --group all --runs 3 --output evaluation/v4/results','.venv/bin/python evaluation/v4/render_report.py','```','','공개 OPEN100/합성 원본·파생 결과는 기존 [NOTICE](../NOTICE.md)의 CC BY-SA 4.0을 따른다. Pāhala는 공공 웹에 공개된 제3자 설계 문서이며 별도 오픈 데이터 라이선스를 가정하지 않는다. 새 주석은 원본 사실을 수동 기록한 평가용 자료이며 원본·전체 OCR·이미지를 Git에 넣지 않았다.']
(HERE/'REPORT.ko.md').write_text('\n'.join(lines)+'\n');(HERE/'summary.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n');print('Rendered 2 figures, report, summary and CSV.')
